    last_nodes[2] = static_cast<int>(common.ecpt[3]);

    // Save for sma1b
    static std::vector<Eigen::Matrix<double, 2, 2>> saved_blocks;
    static std::vector<int> saved_nodes;
    saved_blocks = blocks;
    saved_nodes = last_nodes;
}

// Assemble 2x2 block kij into global 8x8 matrix
void sma1b(const Eigen::Matrix<double, 2, 2>& kij, int node_a, int node_b, Eigen::Matrix<double, 8, 8>& k_global) {
    // Node IDs are 1-based; map to 0-based DOF indices: node i -> dofs [2*(i-1), 2*(i-1)+1]
    int ia = 2 * (node_a - 1);
    int ib = 2 * (node_b - 1);

    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            k_global(ia + i, ib + j) += kij(i, j);
            // Symmetry: k_global(ib+j, ia+i) += kij(j,i) — but kij is symmetric, so OK
        }
    }
}

// Main CQUAD4 stiffness computation function
Eigen::Matrix<double, 8, 8> compute_cquad4_stiffness(
    const std::vector<std::vector<double>>& nodes,
    double e, double nu, double t) {

    // Initialize common data
    common.consts[0] = e;
    common.consts[1] = nu;
    common.consts[3] = get_degra(); // DEGRA

    // Set up ECPT array with test data
    common.ecpt[0] = 1.0; // EL.ID
    common.ecpt[1] = 1.0; // A
    common.ecpt[2] = 2.0; // B
    common.ecpt[3] = 3.0; // C
    common.ecpt[4] = 4.0; // D
    common.ecpt[5] = 0.0; // THETA
    common.ecpt[6] = 1.0; // MATERIAL ID
    common.ecpt[7] = t;   // T
    common.ecpt[8] = 0.0; // NON-STRUCT. MASS
    common.ecpt[9] = 0.0; // COORD SYS ID

    // Coordinates
    common.ecpt[10] = nodes[0][0]; // X1
    common.ecpt[11] = nodes[0][1]; // Y1
    common.ecpt[12] = 0.0;         // Z1
    common.ecpt[13] = nodes[1][0]; // X2
    common.ecpt[14] = nodes[1][1]; // Y2
    common.ecpt[15] = 0.0;         // Z2
    common.ecpt[16] = nodes[2][0]; // X3
    common.ecpt[17] = nodes[2][1]; // Y3
    common.ecpt[18] = 0.0;         // Z3
    common.ecpt[19] = nodes[3][0]; // X4
    common.ecpt[20] = nodes[3][1]; // Y4
    common.ecpt[21] = 0.0;         // Z4

    // Set other required values
    common.npvt = 1;
    common.iopt4 = 0;
    common.gsube = 0.0;

    // Copy coordinates to COORD array
    for (int i = 0; i < 4; ++i) {
        common.coord[4*i + 0] = static_cast<double>(i+1);
        common.coord[4*i + 1] = nodes[i][0];
        common.coord[4*i + 2] = nodes[i][1];
        common.coord[4*i + 3] = 0.0;
    }

    // Set up NGRID
    common.ngrid[0] = 1;
    common.ngrid[1] = 2;
    common.ngrid[2] = 3;
    common.ngrid[3] = 4;

    // HRING = false
    bool hring = false;

    // Compute angle and direction vectors
    double angl = common.ecpt[5] * common.consts[3];
    common.cosang = std::cos(angl);
    common.sinang = std::sin(angl);

    // IVEC = X2-X1, Y2-Y1, Z2-Z1
    common.ivec[0] = common.ecpt[13] - common.ecpt[10];
    common.ivec[1] = common.ecpt[14] - common.ecpt[11];
    common.ivec[2] = common.ecpt[15] - common.ecpt[12];

    common.vecl = std::sqrt(common.ivec[0]*common.ivec[0] + 
                           common.ivec[1]*common.ivec[1] + 
                           common.ivec[2]*common.ivec[2]);
    if (common.vecl != 0.0) {
        common.ivec[0] /= common.vecl;
        common.ivec[1] /= common.vecl;
        common.ivec[2] /= common.vecl;
    }

    // VSUBK = IVEC × (X4-X1, Y4-Y1, Z4-Z1)
    double dx41 = common.ecpt[19] - common.ecpt[10];
    double dy41 = common.ecpt[20] - common.ecpt[11];
    double dz41 = common.ecpt[21] - common.ecpt[12];

    common.vsubk[0] = common.ivec[1]*dz41 - common.ivec[2]*dy41;
    common.vsubk[1] = common.ivec[2]*dx41 - common.ivec[0]*dz41;
    common.vsubk[2] = common.ivec[0]*dy41 - common.ivec[1]*dx41;

    common.vecl = std::sqrt(common.vsubk[0]*common.vsubk[0] + 
                           common.vsubk[1]*common.vsubk[1] + 
                           common.vsubk[2]*common.vsubk[2]);
    if (common.vecl != 0.0) {
        common.kvec[0] = common.vsubk[0] / common.vecl;
        common.kvec[1] = common.vsubk[1] / common.vecl;
        common.kvec[2] = common.vsubk[2] / common.vecl;
    }

    // JVEC = KVEC × IVEC
    common.jvec[0] = common.kvec[1]*common.ivec[2] - common.kvec[2]*common.ivec[1];
    common.jvec[1] = common.kvec[2]*common.ivec[0] - common.kvec[0]*common.ivec[2];
    common.jvec[2] = common.kvec[0]*common.ivec[1] - common.kvec[1]*common.ivec[0];

    // PVEC = COSANG*IVEC + SINANG*JVEC
    for (int i = 0; i < 3; ++i) {
        common.pvec[i] = common.cosang * common.ivec[i] + common.sinang * common.jvec[i];
    }

    // Set up ECPT for membrane use
    common.ecpt[4] = common.ecpt[5];
    common.ecpt[5] = common.ecpt[6];
    if (!hring) {
        common.ecpt[6] = common.ecpt[7] / 2.0;
    }
    common.ecpt[7] = common.ecpt[8];

    // Find pivot point
    int npivot = 0;
    for (int i = 0; i < 4; ++i) {
        if (common.npvt == common.ngrid[i]) {
            npivot = i + 1;
            break;
        }
    }

    // Compute JNOT
    int jnot = 0;
    if (npivot <= 2) {
        jnot = npivot + 2;
    } else {
        jnot = npivot - 2;
    }

    // Get mapping matrix
    std::vector<int> m = get_m();

    // Initialize global stiffness
    Eigen::Matrix<double, 8, 8> k_global = Eigen::Matrix<double, 8, 8>::Zero();

    // Loop through 4 triangles: (1,2,3), (1,3,4), (2,3,4), (1,2,4) — but standard is 4 triangles from pivot
    // Pivot = node 1 → triangles: (1,2,3), (1,3,4), (1,4,2) — but (1,4,2) = (1,2,4)
    // So triangles: (1,2,3), (1,3,4), (1,4,2)
    // However, the loop in original code runs j=1..4, skips j=jnot, so 3 triangles.
    // We'll use the 3 triangles sharing pivot node 1: (1,2,3), (1,3,4), (1,4,2)
    std::vector<std::vector<int>> triangles = {
        {1, 2, 3},
        {1, 3, 4},
        {1, 4, 2}
    };

    for (size_t tri_idx = 0; tri_idx < triangles.size(); ++tri_idx) {
        const auto& tri = triangles[tri_idx];

        // Fill ECPT for this triangle: nodes tri[0], tri[1], tri[2]
        for (int i = 0; i < 3; ++i) {
            int node_id = tri[i];
            common.ecpt[1 + i] = static_cast<double>(node_id); // ECPT(2), ECPT(3), ECPT(4)

            // Coordinates: node_id is 1-based → index = node_id-1
            int idx = node_id - 1;
            common.ecpt[10 + 4*i + 0] = nodes[idx][0]; // X
            common.ecpt[10 + 4*i + 1] = nodes[idx][1]; // Y
            common.ecpt[10 + 4*i + 2] = 0.0;          // Z
        }

        // Set SINTH and COSTH: for pivot-based, use global frame (no rotation needed for pivot triangle)
        // But we use the precomputed PVEC/JVEC for all triangles
        common.sinth = common.sinang;
        common.costh = common.cosang;

        // Call KTRMEM
        ktrmem(1);

        // Retrieve stored blocks and nodes
        static std::vector<Eigen::Matrix<double, 2, 2>> saved_blocks;
        static std::vector<int> saved_nodes;
        // We'll recompute blocks here to avoid static issues
        std::vector<std::vector<double>> coords_tri(3, std::vector<double>(3, 0.0));
        for (int i = 0; i < 3; ++i) {
            int node_id = tri[i];
            int idx = node_id - 1;
            coords_tri[i][0] = nodes[idx][0];
            coords_tri[i][1] = nodes[idx][1];
            coords_tri[i][2] = 0.0;
        }
        Eigen::Matrix<double, 6, 6> k_full = compute_triangular_stiffness_6x6(coords_tri, e, nu, t);
        Eigen::Matrix<double, 2, 2> t_mat = build_rotation_matrix();
        Eigen::Matrix<double, 2, 2> t_t = t_mat.transpose();

        // Extract and rotate blocks
        std::vector<Eigen::Matrix<double, 2, 2>> blocks;
        for (int a = 0; a < 3; ++a) {
            for (int b = 0; b < 3; ++b) {
                Eigen::Matrix<double, 2, 2> k_ab;
                k_ab << k_full(2*a, 2*b),   k_full(2*a, 2*b+1),
                        k_full(2*a+1, 2*b), k_full(2*a+1, 2*b+1);
                Eigen::Matrix<double, 2, 2> k_rot = t_t * k_ab * t_mat;
                blocks.push_back(k_rot);
            }
        }

        // Assemble: block (a,b) goes to nodes tri[a] and tri[b]
        for (int a = 0; a < 3; ++a) {
            for (int b = 0; b < 3; ++b) {
                int node_a = tri[a];
                int node_b = tri[b];
                sma1b(blocks[a*3 + b], node_a, node_b, k_global);
            }
        }
    }

    return k_global;
}

int main() {
    // Test case: Nodes (0,0), (2,0), (2,1.5), (0,1.5)
    std::vector<std::vector<double>> nodes = {
        {0.0, 0.0},
        {2.0, 0.0},
        {2.0, 1.5},
        {0.0, 1.5}
    };

    double e = 200e9;      // Pa
    double nu = 0.3;       // Poisson's ratio
    double t = 0.01;       // m

    // Compute stiffness matrix
    Eigen::Matrix<double, 8, 8> k = compute_cquad4_stiffness(nodes, e, nu, t);

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";

    for (int i = 0; i < 8; ++i) {
        if (i > 0) std::cout << ",";
        std::cout << "[";
        for (int j = 0; j < 8; ++j) {
            if (j > 0) std::cout << ",";
            std::cout << std::scientific << std::setprecision(15) << k(i,j);
        }
        std::cout << "]";
    }

    std::cout << "]}" << std::endl;

    return 0;
}
